// ============================================================
// EXTRAI DADOS E SALVA - roda para TODAS as mensagens do grupo
// (independente de mencionar o bot)
// Captura: texto, mídia, mensagens citadas (quoted)
// ============================================================
const body = $input.first().json;
const b = body.body || {};

// Green API
const gMsg = b.messageData || {};
const gText = gMsg.textMessageData?.textMessage || gMsg.extendedTextMessageData?.text || '';
const gSender = b.senderData?.senderName || b.senderData?.senderContactName || '';
const gMsgId = b.idMessage || gMsg.idMessage || '';
const gChat = b.senderData?.chatId || '';

// Evolution API
const eData = b.data || b || {};
const eMsg = eData.message || {};
const eText = eMsg.conversation || eMsg.extendedTextMessage?.text || eMsg.imageMessage?.caption || eMsg.videoMessage?.caption || '';
const eSender = eData.pushName || '';
const eMsgId = eData.key?.id || '';
const eChat = eData.key?.remoteJid || '';
// Extrai numero do remetente (participant em grupo, remoteJid em DM)
const eParticipant = eData.key?.participant || eData.key?.participantPn || eData.key?.senderPn || '';
const eFromJid = eParticipant || (eData.key?.remoteJid && !String(eData.key.remoteJid).includes('@g.us') ? eData.key.remoteJid : '');
const senderNumber = String(eFromJid).split('@')[0].replace(/\D/g,'');


// Detecta tipo de mídia quando não tem texto
let mediaTag = '';
if (!eText && !gText) {
  if (eMsg.imageMessage) mediaTag = '[imagem]';
  else if (eMsg.videoMessage) mediaTag = '[vídeo]';
  else if (eMsg.audioMessage || eMsg.pttMessage) mediaTag = '[áudio]';
  else if (eMsg.stickerMessage) mediaTag = '[figurinha]';
  else if (eMsg.contactMessage || eMsg.contactsArrayMessage) mediaTag = '[contato]';
  else if (eMsg.locationMessage || eMsg.liveLocationMessage) mediaTag = '[localização]';
  else if (eMsg.documentMessage) mediaTag = '[documento: ' + (eMsg.documentMessage.fileName || 'arquivo') + ']';
  else if (eMsg.reactionMessage) mediaTag = '[reação: ' + (eMsg.reactionMessage.text || '') + ']';
}

// Captura contexto de mensagem citada (quoted/reply)
let quotedContext = '';
const ctxInfo = eMsg.extendedTextMessage?.contextInfo || eMsg.imageMessage?.contextInfo || eMsg.videoMessage?.contextInfo || eMsg.audioMessage?.contextInfo || {};
const quotedMsg = ctxInfo.quotedMessage;
if (quotedMsg) {
  const qText = quotedMsg.conversation || quotedMsg.extendedTextMessage?.text || quotedMsg.imageMessage?.caption || '';
  if (qText) {
    quotedContext = ' [em resposta a: "' + qText.substring(0, 300) + '"]';
  }
}

const textMessage = gText || eText || mediaTag;
const sender = gSender || eSender || 'Alguém';
const messageId = gMsgId || eMsgId || ('tmp_' + Date.now());
const chatId = gChat || eChat;

// Só ignora se não tiver nenhum conteúdo identificável
if (!textMessage) {
  return [];
}

// Monta mensagem final com contexto de citação
const finalMessage = textMessage + quotedContext;

// Detecta tipo de atendimento automaticamente
const msgLower = finalMessage.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
let tipoAtendimento = null;

// Palavras que indicam RESOLUÇÃO (especialmente com mensagem citada)
const resolucaoKeys = ['resolvido', 'finalizado', 'concluido', 'pronto', 'feito', 'normalizado', 'restabelecido', 'ok feito', 'ja foi'];
const isResolucao = resolucaoKeys.some(k => msgLower.includes(k));

// Palavras que indicam SOLICITAÇÃO de serviço
const solicitacaoKeys = ['sem internet', 'sem sinal', 'sem conexao', 'caiu a internet', 'caiu o sinal', 'esta sem', 'ta sem', 'cliente sem', 'problema', 'rompimento', 'sem fibra', 'onu apagada', 'onu vermelha', 'luz vermelha', 'instalar', 'instalacao', 'retirada', 'cancelamento', 'mudanca de endereco', 'upgrade', 'downgrade'];
const isSolicitacao = solicitacaoKeys.some(k => msgLower.includes(k));

if (isResolucao) {
  tipoAtendimento = 'resolucao';
} else if (isSolicitacao) {
  tipoAtendimento = 'solicitacao';
}

return [{ json: { senderNumber, dbRemetente: sender,
    dbMensagem: finalMessage,
    messageId,
    chatId,
    tipoAtendimento
  }
}];

// ============================================================
// VERIFICA MENÇÃO - só continua se o bot foi mencionado
// ============================================================
const body = $('Webhook').first().json;
const b = body.body || {};

// Green API
const gMsg = b.messageData || {};
const gText = gMsg.textMessageData?.textMessage || gMsg.extendedTextMessageData?.text || '';
const gChat = b.senderData?.chatId || '';

// Evolution API
const eData = b.data || b || {};
const eMsg = eData.message || {};
const eText = eMsg.conversation || eMsg.extendedTextMessage?.text || '';
const eChat = eData.key?.remoteJid || '';

const textMessage = gText || eText;
const chatId = gChat || eChat;
// Ignora mensagens antigas (histórico de sincronização da Evolution API)
const msgTimestamp = eData.messageTimestamp || 0;
const nowTimestamp = Math.floor(Date.now() / 1000);
if (msgTimestamp && (nowTimestamp - msgTimestamp) > 120) {
  return []; // mensagem com mais de 2 minutos, ignora
}

// Verifica menção de forma precisa (não usa fullContent para evitar falsos positivos)
const botNumbers = ['554396543242', '235437994062039'];

// 1. Checa mentionedJid (Evolution API)
const mentionedJids = eMsg.extendedTextMessage?.contextInfo?.mentionedJid ||
  eMsg.imageMessage?.contextInfo?.mentionedJid || [];
const isMentionedJid = mentionedJids.some(jid => botNumbers.some(n => jid.includes(n)));

// 2. Checa @menção no texto
const isMentionedText = botNumbers.some(n => textMessage.includes('@' + n) || textMessage.includes('@' + n.slice(2)));

// 3. Checa se é mensagem direta (não grupo)
const isDirectMessage = chatId && !chatId.includes('@g.us');

if (!isMentionedJid && !isMentionedText && !isDirectMessage) {
  return [];
}

const txtLower = textMessage.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Detecta tipo de relatório
const isReportMensal = txtLower.includes('mensal') || /\bmes\b/.test(txtLower) || txtLower.includes('mês');
const isReportSemanal = !isReportMensal && (txtLower.includes('semanal') || txtLower.includes('semana'));
const isReport = txtLower.includes('relatorio') || txtLower.includes('resumo');
const reportType = isReportMensal ? 'mensal' : isReportSemanal ? 'semanal' : 'diario';

const isTraining = txtLower.startsWith('claude aprenda') || txtLower.startsWith('claude correcao') ||
  textMessage.toLowerCase().includes('claude aprenda') || textMessage.toLowerCase().includes('claude correcao');


// Detecção de skill command — precedência: isTraining > isReport > isSkillCommand
// Busca /comando em qualquer posição (ex: "@bot /menu" ou "/menu")
const skillMatch = !isTraining && !isReport ? textMessage.match(/(?:^|\s)(\/\S+)/) : null;
const isSkillCommand = !!skillMatch;
const skillName = isSkillCommand ? skillMatch[1].toLowerCase() : null;
const skillArgs = isSkillCommand ? textMessage.slice(textMessage.indexOf(skillMatch[1]) + skillMatch[1].length).trim() : '';

// Extrai contexto de mensagem citada (quoted/reply)
const ctxInfoV = eMsg.extendedTextMessage?.contextInfo || eMsg.imageMessage?.contextInfo || eMsg.audioMessage?.contextInfo || {};
const quotedMsgV = ctxInfoV.quotedMessage;
let quotedText = '';
if (quotedMsgV) {
  quotedText = (quotedMsgV.conversation || quotedMsgV.extendedTextMessage?.text || quotedMsgV.imageMessage?.caption || '').substring(0, 500);
}

return [{ json: { chatId, textMessage, quotedText, isReport, isTraining, reportType, isSkillCommand, skillName, skillArgs } }];

// ============================================================
// MONTA PROMPT - MÁXIMA PERFORMANCE + LEIA SEMPRE
// ============================================================

// HISTORICO REDIS
let redisHistory = [];
// Bug 19 (reincidência): respostas antigas do bot dizendo "ferramenta fora/indisponível"
// vão como turnos `assistant` reais nas messages — Claude copia o padrão e responde
// sem chamar a tool. Scrub agressivo aqui (vetor mais forte que o histórico em texto).
const FAIL_CONTAMINATION_REDIS = /(ferramenta|tool)[\s\S]{0,40}(fora\s+do\s+ar|fora\s+no\s+momento|indispon[ií]vel|n[ãa]o\s+respond|n[ãa]o\s+est[áa]\s+funcion|off\s*line|tá fora|ta fora)/i;
try {
  const rv = $('Busca Histórico Redis').first().json?.propertyName || $('Busca Histórico Redis').first().json?.value;
  if (rv) {
    redisHistory = JSON.parse(rv).filter(m => m.content && (typeof m.content === 'string' ? m.content.trim() : true));
    // Reescreve respostas contaminantes do assistant
    redisHistory = redisHistory.map(m => {
      if (m.role !== 'assistant') return m;
      if (typeof m.content === 'string' && FAIL_CONTAMINATION_REDIS.test(m.content)) {
        return { ...m, content: '[turno anterior removido — bug de ferramenta corrigido, agora funciona]' };
      }
      if (Array.isArray(m.content)) {
        const newContent = m.content.map(c => {
          if (c && c.type === 'text' && typeof c.text === 'string' && FAIL_CONTAMINATION_REDIS.test(c.text)) {
            return { ...c, text: '[turno anterior removido — bug de ferramenta corrigido, agora funciona]' };
          }
          return c;
        });
        return { ...m, content: newContent };
      }
      return m;
    });
    // Prefixa content com [DD/MM HH:MM] usando ts salvo no Redis e descarta ts
    // (Claude API rejeita campos extras em messages). Turnos antigos sem ts ficam sem prefixo.
    redisHistory = redisHistory.map(m => {
      const { ts, ...rest } = m;
      if (ts && typeof rest.content === 'string') {
        try {
          const d = new Date(new Date(ts).getTime() - 3 * 60 * 60 * 1000);
          const iso = d.toISOString();
          const stamp = `${iso.substring(8,10)}/${iso.substring(5,7)} ${iso.substring(11,16)}`;
          rest.content = `[${stamp}] ${rest.content}`;
        } catch(e) {}
      }
      return rest;
    });
  }
} catch(e) {}

// CHAMADOS — disponíveis via tool buscar_chamados (não injeta no prompt para economizar tokens)
let chamadosContext = '';
// Chamados agora são buscados sob demanda via tool buscar_chamados no agent loop.


// GRUPO ATUAL — tipos permitidos para filtro de tarefas
let grupoTipos = [];
let grupoNome = '';
try {
  const grupoInfo = $('Busca Grupo Atual').first().json;
  grupoNome = grupoInfo?.nome || '';
  const tiposRaw = grupoInfo?.tipos_filtro_entrega;
  if (Array.isArray(tiposRaw) && tiposRaw.length > 0) {
    grupoTipos = tiposRaw.map(t => (t || '').toLowerCase().trim());
  }
} catch(e) {}

// TAREFAS NOTION — filtradas pelo escopo do grupo atual
let tarefasContext = '';
try {
  const notionResp = $('Busca Tarefas Notion').first().json;
  const allResults = notionResp?.results || [];
  // Filtra por tipo do grupo: se grupoTipos está configurado, só mostra tarefas do grupo
  const results = grupoTipos.length > 0
    ? allResults.filter(p => {
        const tiposTask = (p.properties?.['Tipo']?.multi_select || []).map(t => (t.name || '').toLowerCase().trim());
        return tiposTask.length === 0 || tiposTask.some(t => grupoTipos.includes(t));
      })
    : allResults;
  if (results.length > 0) {
    const fmt = (p) => {
      const props = p.properties || {};
      const pageId = (p.id || '').replace(/-/g, '');
      const desc = props['Descrição']?.title?.map(t => t.plain_text).join('') || '(sem descrição)';
      const cliente = props['Cliente']?.rich_text?.map(t => t.plain_text).join('') || '';
      const status = props['status']?.select?.name || '';
      const data = props['Data']?.date?.start || '';
      const entrega = props['Entrega']?.date?.start || '';
      const tipo = (props['Tipo']?.multi_select || []).map(t => t.name).join(', ');
      const obs = props['Obs']?.rich_text?.map(t => t.plain_text).join('') || '';
      const resp = (props['Responsável']?.people || []).map(pe => pe.name || pe.id).join(', ');
      let line = `- [id:${pageId}] [${status || 'sem status'}] ${desc}`;
      if (cliente) line += ` | cliente: ${cliente}`;
      if (tipo) line += ` | tipo: ${tipo}`;
      if (data) line += ` | data: ${data}`;
      if (entrega) line += ` | entrega: ${entrega}`;
      if (resp) line += ` | responsável: ${resp}`;
      if (obs) line += ` | obs: ${obs.substring(0, 200)}`;
      return line;
    };
    const linhas = results.map(fmt).join('\n');
    tarefasContext = '\n\n📋 TAREFAS NO NOTION (atualizadas agora, ' + results.length + ' tarefas):\n'
      + 'Quando perguntarem sobre tarefas, status (parado, em andamento, concluído), responsáveis ou prazos, USE A LISTA ABAIXO como fonte única.\n'
      + 'Para listas longas, agrupe por status. Nunca invente tarefas que não estão aqui.\n'
      + 'Cada tarefa tem [id:<hash>] no inicio da linha. Use esse id para marcar como Ok.\n\n'
      + 'PARA MARCAR UMA TAREFA COMO OK NO NOTION (quando alguem disser que resolveu/concluiu/fechou):\n'
      + 'Emita no FIM da resposta (uma vez por tarefa marcada):\n'
      + '|||NOTION_OK|||{"page_id":"<id da tarefa>","titulo":"<descricao curta>","cliente":"<nome cliente>"}|||FIM|||\n'
      + 'Use SEMPRE o id exato da lista abaixo (sem traços). Nao invente ids. Se ambiguo, pergunte qual.\n'
      + 'Se for confirmar acao do usuario ("Sim", "pode marcar"), olhe no historico qual tarefa estava sendo discutida e use o id ela.\n\n'
      + linhas.substring(0, 6000);
  }
} catch(e) {}


// RESOLVIDOS HOJE (diff de snapshots — quem fechou quantos chamados)
let resolvidosContext = '';
try {
  const resp = $('Busca Resolvidos Hoje').first().json;
  if (resp && resp.total_resolvidos > 0 && resp.ai_text) {
    resolvidosContext = '\n\n🏁 CHAMADOS RESOLVIDOS HOJE (calculado por diff de snapshots — DADOS OFICIAIS):\n'
      + 'Quando perguntarem "quem resolveu chamados hoje", "quantos chamados o fulano fechou", "ranking", USE este bloco.\n'
      + 'Os números são EXATOS, pré-calculados. Nunca reconte ou invente.\n\n'
      + resp.ai_text;
  }
} catch(e) {}

// REMETENTE
let remetente = '';
try { remetente = $('Extrai Dados Mensagem').first().json?.dbRemetente || ''; } catch(e) {}

// 1. REGRAS
let rules = '';
try {
  const rulesData = $('Busca Regras').all().map(r => r.json.regra).filter(Boolean);
  rules = [...new Set(rulesData)].slice(0, 30).join('\n- ');
} catch(e) {}
const rulesPrompt = rules ? '\n\n⚠️ REGRAS ADICIONAIS DE TREINAMENTO (Siga Rigorosamente):\n- ' + rules : '';


// SKILL CONTEXT
let skillContext = '';
try {
  const skillName = $('Verifica Menção').first().json?.skillName || null;
  if (skillName) {
    const skills = $('Busca Skills').all().map(s => s.json).filter(s => s.nome);
    const skill = skills.find(s => s.nome === skillName);
    if (skill?.prompt_base) {
      const skillArgs = $('Verifica Menção').first().json?.skillArgs || '';
      skillContext = '\n\n[SKILL] SKILL ATIVADA: ' + skillName + '\n' + skill.prompt_base;
      if (skillArgs) skillContext += '\n\nParametros: ' + skillArgs;
    }
  }
} catch(e) {}

// 2. SYSTEM PROMPT
let systemPromptTemplate = null;
try {
  const spRows = $('Busca System Prompt').all().map(d => d.json);
  for (const r of spRows) {
    if (r.chave === 'system_prompt' && r.valor) { systemPromptTemplate = r.valor; break; }
  }
  if (systemPromptTemplate && systemPromptTemplate.length > 50000) {
    systemPromptTemplate = systemPromptTemplate.substring(0, 50000) + '\n[...truncado...]';
  }
} catch(e) {}

// 3. HISTÓRICO DO GRUPO
let historicoSection = '';
try {
  const histRows = $('Busca Histórico 10').all().map(e => e.json);
  const histMap = new Map();
  for (const h of histRows) { if (h.id) histMap.set(h.id, h); }
  const uniqueHist = Array.from(histMap.values()).sort((a,b) => a.id - b.id).slice(-10);
  let historico = '';
  // Bug 19/contamination: respostas antigas do bot dizendo "ferramenta fora/indisponível"
  // viram self-fulfilling prophecy quando reinjetadas no histórico. Scrub.
  const FAIL_CONTAMINATION = /(ferramenta|tool)[\s\S]{0,40}(fora\s+do\s+ar|fora\s+no\s+momento|indispon[ií]vel|n[ãa]o\s+respond|n[ãa]o\s+est[áa]\s+funcion|off\s*line)/i;
  for (const msg of uniqueHist) {
    // Formato [DD/MM HH:MM] em BRT — Claude precisa da data pra não confundir
    // mensagens de dias anteriores com "hoje" (bug 18/05/2026: relatório listou
    // chamados de sábado como "resolvidos hoje" porque só hora estava no prompt).
    let prefixo = '??/?? ??:??';
    try {
      const d = new Date(new Date(msg.data_hora).getTime() - 3 * 60 * 60 * 1000);
      const iso = d.toISOString();
      prefixo = `${iso.substring(8,10)}/${iso.substring(5,7)} ${iso.substring(11,16)}`;
    } catch(e) {}
    let texto = (msg.mensagem || '').substring(0, 400);
    if (FAIL_CONTAMINATION.test(texto)) texto = '[resposta antiga do bot removida — bug de ferramenta corrigido]';
    historico += `[${prefixo}] ${msg.remetente}: ${texto}\n`;
  }
  if (historico) historicoSection = `\n\nÚLTIMAS MENSAGENS DO GRUPO:\n${historico}`;
} catch(e) {}

// 3b. EXTRAI TEXTO DA MENSAGEM (necessário para busca semântica de POPs)
let _vM_early;
try { _vM_early = $('Verifica Menção').first().json; if (!_vM_early.chatId || !_vM_early.textMessage) _vM_early = null; } catch(e) {}
if (!_vM_early) try { _vM_early = $('Formata Transcrição').first().json; if (!_vM_early.chatId) _vM_early = null; } catch(e) {}
if (!_vM_early) try { _vM_early = $('Formata Imagem').first().json; } catch(e) { _vM_early = {}; }
const textMessage = _vM_early.textMessage || '';
const quotedText = _vM_early.quotedText || '';

// 4. POPs — BUSCA SEMÂNTICA (top 5 relevantes + todos os títulos)
const allPopsInputs = $("Busca POPs").all().map(i => i.json).filter(p => p.titulo);
const popMap = new Map();
for (const p of allPopsInputs) {
  if (p.conteudo || !popMap.has(p.titulo)) popMap.set(p.titulo, p);
}
const uniquePops = Array.from(popMap.values());

// Relevância: conta palavras da mensagem que aparecem no POP
const stopwords = ['que','para','como','com','uma','por','dos','das','nao','mas','tem','sao','foi','ele','ela','isso','esse','esta','voce','aqui','hoje','fazer','pode','sobre','mais','tambem','quando','onde','qual','quais','muito','cada','todos','todo','ainda','acho','gente','nosso','nossa','vamos','bom','dia',
  // termos genéricos do domínio ISP — aparecem em todos os POPs e não ajudam na seleção
  'internet','servico','servicos','cliente','clientes','fibra','wifi','rede','zazz','conexao','provedor','suporte','contrato','plano','planos','atendimento','solucao','problema','acesso'];
const normaliza = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const msgPalavras = [...new Set(normaliza(textMessage || quotedText).split(/\s+/).filter(w => w.length > 2 && !stopwords.includes(w)))];

function calcRelevancia(pop) {
  const tituloNorm = normaliza(pop.titulo);
  const popTexto = normaliza(pop.titulo + ' ' + (pop.categoria || '') + ' ' + (pop.conteudo || '').substring(0, 800));
  let score = 0;
  for (const p of msgPalavras) {
    if (popTexto.includes(p)) score++;
    if (tituloNorm.includes(p)) score += 2;
  }
  return score;
}

let clientesContent = '';
const allNonClientTitles = [];
let leiasSemprePops = [];
const importantePops = [];
const scoredPops = [];

for (const pop of uniquePops) {
  const cat = (pop.categoria || '').toLowerCase();
  const titulo = (pop.titulo || '').toLowerCase();
  const isClientDB = cat.includes('cliente') || cat.includes('banco') || cat.includes('base') || cat.includes('crm');
  const prio = (pop.prioridade || 'relevante').toLowerCase();

  if (isClientDB) {
    if (pop.conteudo) clientesContent += pop.conteudo + '\n';
  } else if (prio === 'sempre') {
    if (pop.conteudo) leiasSemprePops.push(pop);
    allNonClientTitles.push(pop);
  } else if (prio === 'importante') {
    allNonClientTitles.push(pop);
    if (pop.conteudo) importantePops.push(pop);
  } else {
    allNonClientTitles.push(pop);
    if (pop.conteudo) scoredPops.push({ pop, score: calcRelevancia(pop) });
  }
}

// POPs não-LEIA SEMPRE: só títulos (conteúdo disponível via tool buscar_pop)
const todosNaoLeiasSempre = [...importantePops, ...scoredPops.map(s => s.pop)];

// 5. COLABORADORES
let colaboradoresArray = [];
try {
  const colabRows = $('Busca Colaboradores').all().map(i => i.json).filter(c => c.nome);
  const colabMap = new Map();
  for (const c of colabRows) colabMap.set(c.nome, c);
  colaboradoresArray = Array.from(colabMap.values());
} catch(e) {}

// 6. DADOS DA MENSAGEM
const _vM = _vM_early || {};
const chatId = _vM.chatId || '';

const now = new Date();
const brt = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dia = brt.getDate().toString().padStart(2,'0');
const mes = (brt.getMonth()+1).toString().padStart(2,'0');
const ano = brt.getFullYear();
const today = `${ano}-${mes}-${dia}`;
const diasSemana = ['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
const diaSemana = diasSemana[brt.getDay()];

// CALEND\u00c1RIO 8 dias \u2014 substitui {{PROXIMOS_DIAS}} no sysprompt. Bot usa como tabela de
// refer\u00eancia absoluta pra "hoje/amanh\u00e3/depois", em vez de calcular manualmente.
const _proximosDiasArr = [];
for (let i = 0; i < 8; i++) {
  const _dt = new Date(brt.getFullYear(), brt.getMonth(), brt.getDate() + i);
  const _dd = String(_dt.getDate()).padStart(2, '0');
  const _mm = String(_dt.getMonth() + 1).padStart(2, '0');
  const _yyyy = _dt.getFullYear();
  const _label = i === 0 ? 'HOJE = ' : (i === 1 ? 'AMANH\u00c3 = ' : '');
  _proximosDiasArr.push(`${_label}${_dd}/${_mm}/${_yyyy} (${diasSemana[_dt.getDay()]})`);
}
const proximosDiasStr = _proximosDiasArr.join('\n');

const msgLower = textMessage.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// 7. MONTAGEM DOS POPs — apenas títulos (conteúdo via tool buscar_pop)
const isListingPops = msgLower === '/pops' || msgLower.includes('listar pops') || msgLower.includes('quais pops') || msgLower.includes('quais procedimentos') || msgLower.startsWith('lista de pop');
let pops = '';

