// Dispara quando mensagem do grupo contem keyword de "resolvido".
// REFATORADO mai/2026: regex mais restrito + exclusão de mensagens que CRIAM tarefa
// (bug: "Avisar quando tiver pronto" disparava falso-positivo)
const body = $input.first().json.body || $input.first().json;

const eData = body.data || {};
const eMsg = eData.message || {};
const eText = eMsg.conversation || eMsg.extendedTextMessage?.text
  || eMsg.imageMessage?.caption || eMsg.videoMessage?.caption || '';
const eKey = eData.key || {};
const eSender = eData.pushName || eKey.participant?.split('@')[0] || '';

const gMsg = body.messageData || {};
const gText = gMsg.textMessageData?.textMessage || gMsg.extendedTextMessageData?.text || '';
const gSender = body.senderData?.senderName || '';
const gKey = { id: body.idMessage || '', remoteJid: body.senderData?.chatId || '' };

const text = (eText || gText || '').trim();
const sender = eSender || gSender || 'Desconhecido';
const chatId = eKey.remoteJid || gKey.remoteJid || '';
const messageId = eKey.id || gKey.id || '';

if (!text || !chatId) return [];
if (eKey.fromMe) return [];

// Normaliza: minusculas + remove acentos pra simplificar regex
const norm = text.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

// EXCLUSÃO: mensagens que claramente CRIAM tarefa nova (template de pedido)
// Bug 06/05/2026: "Avisar ele quando tiver pronto" disparava o auto-resolve
const CRIA_TAREFA_RE = /(descricao do servico|titulo:|cliente:|data de entrega|tamanho:|telefone:|observacao:|valor:|obs:|quando (?:tiver|ficar|estiver)\s+pronto|me\s+avis(?:e|a)\s+quando|avisar?\s+(?:ele|ela|quando)|quero\s+(?:um|uma)|criar?\s+(?:um|uma)?\s*(?:tarefa|pedido|orcamento)|orcamento\s+(?:de|para))/i;
if (CRIA_TAREFA_RE.test(norm)) return [];

// EXCLUSÃO: mensagens muito longas (>800 chars) raramente são confirmação,
// geralmente são briefings/pedidos novos
if (text.length > 800) return [];

// Regex restrito: exige contexto de "JÁ está pronto/feito/ok", não só "pronto" solto
// Combinações válidas:
//   - "ficou pronto", "tá pronto", "já tá pronto", "esta pronto"
//   - "concluído", "concluida", "finalizado", "encerrado"
//   - "resolvido", "resolvida", "já foi resolvido"
//   - "terminei", "finalizei", "fechei" (1ª pessoa = afirmação direta)
//   - "tudo certo", "tudo ok"
const KEY_RE = /\b(resolvid[oa]|finalizad[oa]|encerrad[oa]|conclu[ií]d[oa]|j[áa]\s+(?:foi|ficou|est[áa])\s+(?:pronto|ok|feito|resolv|finalizad|conclu)|fic(?:ou|ar(?:am)?)\s+(?:pronto|ok|feito|resolv)|t[áa]\s+(?:pronto|ok|feito|resolv|finalizad)|est[áa]\s+(?:pronto|ok|feito|resolv|finalizad)|terminei|finalizei|fechei|resolvi(?!\b\s+do)|tudo\s+(?:ok|certo|resolv))/;
if (!KEY_RE.test(norm)) return [];

return [{ json: { text, sender, chatId, messageId } }];

