parameters.jsCode:
// Extrai a acao do Claude e propaga adiante
const resp = $input.first().json;
let raw = resp?.content?.[0]?.text || '';
raw = raw.trim();
// Tira ```json...``` se vier
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const m = raw.match(/\{[\s\S]*\}/);
if (!m) return [];

let parsed;
try { parsed = JSON.parse(m[0]); } catch(e) { return []; }

const detecta = $('Detecta Resolvido').first().json;
let action = parsed.action || 'nenhum';

// Defesa: se Claude listou MUITOS candidatos como ambiguo, e suspeito — trata como nenhum
if (action === 'ambiguo' && Array.isArray(parsed.candidatos) && parsed.candidatos.length > 3) {
  action = 'nenhum';
}

if (action === 'nenhum') return [];  // mata silencioso

if (action === 'resolve' && parsed.page_id) {
  return [{
    json: {
      action: 'resolve',
      page_id: parsed.page_id,
      titulo: parsed.titulo || '(sem titulo)',
      cliente: parsed.cliente || '',
      chatId: detecta.chatId,
      message: '✅ Marquei como Ok no Notion: *' + (parsed.titulo || '(sem titulo)') + '*'
        + (parsed.cliente ? '\n_Cliente:_ ' + parsed.cliente : '')
    }
  }];
}

if (action === 'ambiguo' && Array.isArray(parsed.candidatos) && parsed.candidatos.length > 0) {
  const lista = parsed.candidatos.slice(0, 3).map((c, i) => (i+1) + '. ' + (c.titulo || c.page_id)).join('\n');
  return [{
    json: {
      action: 'ambiguo',
      chatId: detecta.chatId,
      message: '🤔 Achei mais de uma tarefa parada que pode ser. Qual voce resolveu?\n\n' + lista
    }
  }];
}

return [];

// Recebe 1 item com notionBodies (array). Emite N items, um por body.
const inp = $input.first().json;
const bodies = Array.isArray(inp.notionBodies) ? inp.notionBodies : [];

if (bodies.length === 0) {
  // fallback: se nao tem array mas tem notionBody simples, usa ele
  if (inp.notionBody) {
    return [{ json: { ...inp, notionBody: inp.notionBody } }];
  }
  return [];
}

return bodies.map(body => ({
  json: {
    chatId: inp.chatId,
    notionBody: body,
    hasNotion: true
  }
}));

// Recebe 1 item com notionOks (array). Emite N items, um por OK.
const inp = $input.first().json;
const oks = Array.isArray(inp.notionOks) ? inp.notionOks : [];
if (oks.length === 0) return [];
return oks.map(ok => ({
  json: {
    chatId: inp.chatId,
    page_id: ok.page_id,
    titulo: ok.titulo || '',
    cliente: ok.cliente || '',
    senderName: inp.senderName || ''
  }
}));

// NO-OP: alertas Ok agora sao centralizados no workflow Urf233 (polling 5min do Notion).
// Esse no fica pra preservar o pipeline existente; nao envia mais notificacao
// (evita duplicacao quando o bot marca via tool resolver_tarefa_notion).
return [];
